        // ShrincsWallet beta-v1.0.2 requires this branch
        // for compatibility
        if (data.length >= 0x20 && uint256(bytes32(data[0:0x20])) == 0xc0) {
            (, , , , , vector) = Codec.decodeUpgradeAuth(data);
        }
