    ///      its own policy decision". This wallet's contract is never-revert-on-bad-signature
    ///      validation (ERC-4337 returns 1) and never-revert ERC-1271, so EVERY verifier revert
    ///      maps to "invalid signature". Malformed ABI framing of the blob itself is handled
    ///      before the verifier is reached (behind the `userOpEnvelope` / `erc1271Envelope`
    ///      self-staticcalls on the validation paths — INVARIANTS §19). Accepted trade-off: an
    ///      inner out-of-gas is also
    ///      reported as an invalid signature instead of propagating.
    function _tryVerifyStateful(
        bytes32 expectedCommitment,
        bytes32 messageHash,
        bytes memory envelope
    ) internal view returns (bool) {
        try
            IERC7913SignatureVerifier(SHRINCS_VERIFIER).verify(
                abi.encodePacked(expectedCommitment),
                messageHash,
                envelope
            )
        returns (bytes4 result) {
            return result == IERC7913SignatureVerifier.verify.selector;
        } catch {
            return false;
        }
    }

    /// @dev Stateless twin of `_tryVerifyStateful` (identical revert policy), targeting the
    ///      verifier's `verifyStateless` entrypoint.
    function _tryVerifyStateless(
        bytes32 expectedCommitment,
        bytes32 messageHash,
        bytes memory envelope
    ) internal view returns (bool) {
        try
            SHRINCSVerifier(SHRINCS_VERIFIER).verifyStateless(
                abi.encodePacked(expectedCommitment),
                messageHash,
                envelope
            )
        returns (bytes4 result) {
            return result == IERC7913SignatureVerifier.verify.selector;
        } catch {
            return false;
        }
    }

    /// @dev External-verifier image of `SHRINCS.statelessRotate` (SHRINCS.sol). Division of
    ///      labor: the pinned verifier re-runs the CURRENT-bundle checks (commitment match +
    ///      shape, inside `prepareStatelessDelegation`) plus the FORS-C/hypertree crypto, so
    ///      the wallet keeps only what the verifier can never see — the rotation TARGET.
    ///      `nextKey`'s structural validation also keeps `fullRotationMessageHash`'s packed
    ///      preimage canonical, and the declared-vs-recomputed equality is the authorization
    ///      semantics: the signature binds the DECLARED commitment bytes (via the message
    ///      hash), the wallet installs the RECOMPUTED value — equality makes those the same
    ///      thing. Returns the next bundle commitment, or bytes32(0) on any failure.
    function _statelessRotate(
        bytes32 expectedCommitment,
        SHRINCS.PublicKey calldata currentPublicKey,
        SHRINCS.RotationContext memory ctx,
        SPHINCSPlusC.Signature calldata recoverySignature,
        SHRINCS.RotationTarget calldata nextKey
    ) internal view returns (bytes32) {
        // The replacement bundle's four fields have fixed widths.
        if (
            nextKey.statefulPublicKey.length !=
            SHRINCSParams.STATEFUL_PUBLIC_KEY_BYTES
        ) return bytes32(0);
        if (nextKey.publicKeyCommitment.length != 32) return bytes32(0);
        if (nextKey.pkSeed.length != 32) return bytes32(0);
        if (nextKey.hypertreeRoot.length != 32) return bytes32(0);
        {
            // Reject unusable zero-budget replacement stateful keys.
            (
                UXMSS.StatefulPublicKey memory decodedNext,
                bool ok
            ) = SHRINCS.decodeStatefulPublicKey(nextKey.statefulPublicKey);
            if (!ok || decodedNext.maxSignatures == 0) return bytes32(0);
        }
        bytes32 computedNext = SHRINCS.publicKeyCommitmentFromParts(
            nextKey.statefulPublicKey,
            nextKey.pkSeed,
            nextKey.hypertreeRoot
        );

        bytes32 declaredNext = abi.decode(
            nextKey.publicKeyCommitment,
            (bytes32)
        );
        if (declaredNext != computedNext) return bytes32(0);

        // The stateless recovery signature must authorize exactly the canonical
        // full-rotation message.
        bytes32 messageHash = SHRINCS.fullRotationMessageHash(
            expectedCommitment,
            currentPublicKey,
            ctx,
            nextKey
        );
        if (
            !_tryVerifyStateless(
                expectedCommitment,
                messageHash,
                abi.encode(currentPublicKey, recoverySignature)
            )
        ) return bytes32(0);

        return computedNext;
    }

    /// @dev The incoming party's half of a `transferOwnership`: a hybrid proof, mirroring the
    ///      wallet's own PQ-AND-ECDSA gate, that whoever receives the wallet controls BOTH keys
    ///      it will be operated with. 
    ///
    ///      Neither half binds the live nonce or epoch. `nextCommitment` can be installed on
    ///      this wallet at most once (lifetime tree registries) and both halves bind it together
    ///      with `newOwner`, so an acceptance authorizes exactly one install of exactly this
    ///      bundle for exactly this owner on this wallet/chain — and stays valid however many
    ///      actions the current owner consumes between the recipient signing and the broadcast.
    ///      The stateful half's context therefore carries nonce 0 / epoch 0 under the wallet's
    ///      domain, with the same `ACTION_TRANSFER_OWNERSHIP` tag and payload as the current
    ///      owner's binding signature: the two messages are distinct because each is bound to
    ///      its own commitment (installed vs. incoming), and no live action of the incoming key
    ///      can ever carry nonce 0 / epoch 0 once it is installed.
    ///
    function _verifyOwnershipAcceptance(
        SHRINCS.RotationTarget calldata nextKey,
        bytes32 nextCommitment,
        address newOwner,
        uint32 nextMaxSignatures,
        SHRINCS.Signature calldata keyAcceptance,
        bytes calldata ownerAcceptance
    ) internal view returns (uint32 leaf) {
        // Classical half: ECDSA for an EOA, ERC-1271 for a contract recipient, over the wallet's
        // `QuipSignedHash` target of the handover payload. That target is also the ERC-1271
        // message surface, but only this wallet's OWNER ever signs it for this wallet, and the
        // recipient is not the owner until this call lands — so nothing harvestable elsewhere
        // can double as an acceptance.
        bytes32 payloadHash = Codec.transferOwnershipPayloadHash(
            newOwner,
            nextCommitment
        );
        if (
            !SignatureCheckerLib.isValidSignatureNowCalldata(
                newOwner,
                quipSignedHashEcdsaTarget(payloadHash),
                ownerAcceptance
            )
        ) revert InvalidOwnerAcceptance();

        // PQ half: a stateful signature from the INCOMING bundle, verified against ITS
        // commitment (not the installed one).
        leaf = _leafIndex(keyAcceptance);
        if (leaf == 0 || leaf > nextMaxSignatures) revert InvalidKeyAcceptance();
        SHRINCS.PublicKey memory nextPk = SHRINCS.PublicKey({
            statefulPublicKey: nextKey.statefulPublicKey,
            publicKeyCommitment: nextKey.publicKeyCommitment,
            pkSeed: nextKey.pkSeed,
            hypertreeRoot: nextKey.hypertreeRoot
        });
        SHRINCS.ActionContext memory ctx = Codec.buildActionContext(
            _shrincsDomainSeparator(),
            0,
            0,
            Codec.ACTION_TRANSFER_OWNERSHIP,
            payloadHash
        );
        if (
            !_tryVerifyStateful(
                nextCommitment,
                SHRINCS.statefulActionMessageHash(nextCommitment, ctx),
                abi.encode(nextPk, keyAcceptance)
            )
        ) revert InvalidKeyAcceptance();
    }

    /// @dev Returns whether stateful `leafIndex` has been consumed in the given key epoch.
    function _isStatefulLeafUsed(
        Storage.Layout storage $,
        uint256 keyVersion_,
        uint256 leafIndex
    ) internal view returns (bool) {
        return
            ($.usedStatefulLeafBitmap[keyVersion_][leafIndex >> 8] &
                (uint256(1) << (leafIndex & 0xff))) != 0;
    }

    /// @dev Marks stateful `leafIndex` consumed in the given key epoch.
    function _markStatefulLeafUsed(
        Storage.Layout storage $,
        uint256 keyVersion_,
        uint256 leafIndex
    ) internal {
        $.usedStatefulLeafBitmap[keyVersion_][leafIndex >> 8] |=
            uint256(1) <<
            (leafIndex & 0xff);
    }

    /// @dev Shared core for `isValidSignature` and `debugIsValidSignature`. Order: length →
    ///      ECDSA (owner) → stateless SHRINCS (dedicated verifier key).
    function _checkErc1271Signature(
        bytes32 hash,
        bytes calldata signature
    ) internal view returns (Erc1271ValidationResult) {
        if (signature.length < 0x60)
            return Erc1271ValidationResult.BadSignatureLength;
        // Non-reverting decode: a malformed blob (out-of-bounds ABI tail offsets) must return the
        // ERC-1271 failure magic, never revert — a revert here is a DoS on the staticcalling
        // relying contract. The reverting decoders remain on the transaction paths.
        (
            bool ok,
            SHRINCS.PublicKey calldata pk,
            SPHINCSPlusC.Signature calldata sig,
            bytes calldata ecdsaSig
        ) = Codec.tryDecodeErc1271Signature(signature);
        if (!ok) return Erc1271ValidationResult.MalformedErc1271Payload;

        address recovered = ECDSA.tryRecoverCalldata(
            quipSignedHashEcdsaTarget(hash),
            ecdsaSig
        );
        if (recovered == address(0) || recovered != owner()) {
            return Erc1271ValidationResult.InvalidEcdsaSignature;
        }

        // Zero-hash membrane: `hash` is the only caller-supplied context field anywhere in
        // the wallet (it rides in `payloadHash` below). The inlined library path rejected
        // payloadHash == 0 inside `validActionContext`; the external verifier never sees
        // the context, so the check lives here.
        if (hash == bytes32(0))
            return Erc1271ValidationResult.InvalidShrincsSignature;

        Storage.Layout storage $ = Storage.layout();
        // Binds the LIVE action nonce: every consumed wallet signature invalidates all
        // outstanding ERC-1271 blobs (intended supersession — integrators re-sign after actions).
        SHRINCS.ActionContext memory ctx = Codec.buildActionContext(
            _shrincsDomainSeparator(),
            $.nonce,
            $.keyVersion,
            Codec.ACTION_ERC1271,
            hash
        );
        // The codec bounds-checks only the blob's TOP-LEVEL tail offsets; the nested
        // PublicKey/Signature tail offsets are first touched by the `abi.encode(pk, sig)`
        // re-encode, where Solidity's calldata accessors REVERT on an overrun. That revert
        // would surface in THIS frame, outside `_tryVerifyStateless`'s try/catch, and the
        // owner ECDSA half of a blob is reusable, so anyone holding a previously shared blob
        // could trigger it. The re-encode therefore runs behind a self-staticcall so the
        // overrun maps to the failure magic like every other rejection (INVARIANTS §19).
        bytes memory envelope;
        try this.erc1271Envelope(signature) returns (bytes memory encoded) {
            envelope = encoded;
        } catch {
            return Erc1271ValidationResult.MalformedErc1271Payload;
        }

        // Stateless verification via the pinned verifier: canonical stateless action hash
        // computed locally; bundle checks + FORS-C/hypertree crypto delegated
        if (
            !_tryVerifyStateless(
                $.erc1271PublicKeyCommitment,
                SHRINCS.statelessActionMessageHash(
                    $.erc1271PublicKeyCommitment,
                    ctx
                ),
                envelope
            )
        ) return Erc1271ValidationResult.InvalidShrincsSignature;

        return Erc1271ValidationResult.Ok;
    }

    /// @dev Sends the per-op execute fee to the factory, if any. Reads the LIVE fee once and
    ///      charges it, reverting only if it exceeds the signer's `maxFee` ceiling — so a fee
    ///      decrease between signing and landing succeeds at the lower price.
    function _collectExecuteFee(uint256 maxFee) internal {
        uint256 fee = getExecuteFee();
        if (fee > maxFee) revert ExecuteFeeExceedsCap(fee, maxFee);
        if (fee > 0) {
            // Paid to the immutable `FACTORY` — the single source of truth — matching the fee
            // read in `getExecuteFee`, so the amount charged and its recipient can never diverge.
            SafeTransferLib.safeTransferETH(FACTORY, fee);
        }
    }

    /// @dev The wallet's canonical SHRINCS signing domain: tag + chainId + this wallet.
    function _shrincsDomainSeparator() internal view returns (bytes32) {
        return
            EfficientHashLib.hash(
                Codec.DOMAIN_TAG,
                bytes32(block.chainid),
                bytes32(uint256(uint160(address(this))))
            );
    }

    /// @dev The currently installed implementation address (ERC-1967 slot).
    function _msgImplementation() internal view returns (address impl) {
        assembly {
            impl := sload(_ERC1967_IMPLEMENTATION_SLOT)
        }
    }

    /// @dev Reverts unless an upgrade into this code is in flight — the sole gate on
    ///      `migrate`. 
    ///       NB: migragte is always called via `delegateCallthis` hence
    ///           `installed` is the address in storage of the CURRENT implementation
    ///           whereas `_SELF` is the address of whichever implementations code
    ///           is currently being run in this current context
    ///           therefore `_SELF` will only be different when a `delegateCall is
    ///           is happening to a new implementation`
    function _enforceUpgradeInFlight() internal view {
        address installed = _msgImplementation();
        if (installed == address(0) || installed == _SELF) revert NotUpgrading();
    }

}

